from html.parser import HTMLParser
class Scan(HTMLParser):
 def __init__(self): super().__init__(); self.ids=set(); self.links=[]; self.img=[]
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if 'id'in a:self.ids.add(a['id'])
  if tag=='a'and'href'in a:self.links.append(a['href'])
  if tag=='img':self.img.append(a)
for name in ['feasibility-architecture-allocations','phase-comparison']:
 p=Path('rendered')/(name+'.html'); s=Scan(); s.feed(p.read_text())
 missing=[]; badanchors=[]
 for link in s.links:
  if ':'in link or link.startswith('//'):continue
  target,_,anchor=link.partition('#')
  dest=p.parent/target if target else p
  if not dest.exists():missing.append(link)
  elif not target and anchor and anchor not in s.ids:badanchors.append(link)
 print(name,'missing local targets',sorted(set(missing)),'bad own anchors',badanchors)
 print('images',[(a.get('src'),a.get('alt'),a.get('width')) for a in s.img])
